import hashlib,json,os,resource,subprocess
subprocess.run(['cargo','build','--offline','--release','-p','kassiber-pydecimal'],check=True)
library=Path('target/release/libkassiber_pydecimal.rlib')
subprocess.run(['rustc','--edition=2021','-O','-L','dependency=target/build/release/deps','--extern',f'kassiber_pydecimal={library}','target/benchmark-wide.rs','-o','target/benchmark-wide'],check=True)
results=[]
for width in (40,60,130,1000,4096):
 trials=[]
 for run in range(5):
  pair={}
  for mode in (['formatter','coefficient'] if run%2==0 else ['coefficient','formatter']):
   load=os.getloadavg();before=resource.getrusage(resource.RUSAGE_CHILDREN)
   subprocess.run(['target/benchmark-wide',mode,str(width)],check=True)
