use kassiber_pydecimal::Decimal;
use std::hint::black_box;
struct Coefficient<'a> {
    left: &'a [u8],
    right: &'a [u8],
    sign: bool,
    exponent: bool,
}
impl std::fmt::Write for Coefficient<'_> {
    fn write_str(&mut self, value: &str) -> std::fmt::Result {
        if self.exponent {
            return Ok(());
        }
        let value = if self.sign {
            self.sign = false;
            value.strip_prefix('-').ok_or(std::fmt::Error)?
        } else {
            value
        };
        let value = if let Some((digits, _)) = value.split_once('E') {
            self.exponent = true;
            digits
        } else {
            value
        };
        if value.len() <= self.left.len() {
            self.left = self
                .left
                .strip_prefix(value.as_bytes())
                .ok_or(std::fmt::Error)?;
        } else {
            let (left, right) = value.as_bytes().split_at(self.left.len());
            if self.left != left {
                return Err(std::fmt::Error);
            }
            self.left = &[];
            self.right = self.right.strip_prefix(right).ok_or(std::fmt::Error)?;
        }
        Ok(())
    }
}


fn main() {
    let mode = std::env::args().nth(1).unwrap();
    let length: usize = std::env::args().nth(2).unwrap().parse().unwrap();
    let raw: String = "1234567890".repeat(length.div_ceil(10)).chars().take(length).collect();
    let decimal: Decimal = format!("{raw}E-32").parse().unwrap();
    let iterations = 20_000_000 / length;
    for _ in 0..iterations {
        let decimal = black_box(&decimal);
        let raw = black_box(raw.as_bytes());
        let equal = if mode == "formatter" {
            let mut matcher = Coefficient { left: raw, right: &[], sign: false, exponent: false };
            decimal.write_canonical(&mut matcher).is_ok() && matcher.left.is_empty() && matcher.right.is_empty()
        } else {
            decimal.coefficient_matches_ascii(raw, &[])
        };
        assert!(black_box(equal));
    }
}

